WITH gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM payments), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT CASE WHEN amount >= 1740 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, MAX(is_new_burst) FILTER (WHERE method = 'card') AS card_max_is_new_burst, COUNT(CASE WHEN status = 'FAILED' THEN 1 END) AS failed_count, ROUND(SUM(session_id) / NULLIF(COUNT(CASE WHEN status = 'FAILED' THEN 1 END), 0), 2) AS session_id_per_failed, STDDEV_SAMP(amount) AS amount_stddev, SUM(CASE WHEN status = 'REFUNDED' THEN session_id ELSE 0 END) AS refunded_session_id FROM sessionized GROUP BY amount_tier HAVING SUM(CASE WHEN status = 'REFUNDED' THEN session_id ELSE 0 END) > 0 ORDER BY failed_count DESC NULLS FIRST;
